;font-weight:700;border-radius:.75rem;padding:.85rem 1rem;margin-top:auto;width:100%;font-size:.93rem;line-height:1.45}.future{padding:1rem 0 5rem}.future-panel{background:var(--soft);border:1px solid var(--line);border-radius:var(--radius);padding:clamp(1.5rem,4vw,3rem)}.future-panel p{color:var(--muted);max-width:900px}.future-points{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin-top:1.5rem}.point{padding:1.15rem;background:var(--card);border-radius:.85rem;border:1px solid var(--line)}.point strong{display:block;margin-bottom:.35rem}.point span{color:var(--muted);font-size:.95rem}footer{text-align:center;color:var(--muted);font-size:.88rem;padding:1.5rem;border-top:1px solid var(--line)}
